<!DOCTYPE html>
<html lang="fr">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<style>
    /* STYLE GÉNÉRAL DE L'OUTIL */
    body { font-family: sans-serif; background: #eee; margin: 0; padding: 10px; }

    /* ZON DE CONTROLE (Le Formulaire) */
    .controls {
        background: white; padding: 20px; border-radius: 10px;
        box-shadow: 0 2px 5px rgba(0,0,0,0.1); margin-bottom: 20px;
        border-top: 5px solid #d35400; /* Couleur Chocolat par défaut */
    }
    .controls h2 { margin-top: 0; color: #333; }

    .form-group { margin-bottom: 15px; }
    .form-group label { display: block; font-weight: bold; margin-bottom: 5px; font-size: 14px;}
    .form-group input, .form-group textarea, .form-group select {
        width: 100%; padding: 10px; border: 1px solid #ddd; border-radius: 5px;
        box-sizing: border-box; /* Important pour mobile */
    }

    .btn-action {
        background: #2c3e50; color: white; border: none; padding: 10px 15px;
        border-radius: 5px; cursor: pointer; margin-right: 5px; margin-top: 5px;
    }
    .btn-print { background: #27ae60; width: 100%; font-size: 18px; margin-top: 20px;}

    /* L'APERÇU DU CV (La feuille A4) */
    #cv-preview {
        background: white; width: 100%; max-width: 800px; margin: 0 auto;
        min-height: 1000px; box-shadow: 0 0 15px rgba(0,0,0,0.2);
        display: flex; flex-direction: row; overflow: hidden;
    }

    /* Colonne Gauche CV */
    .cv-left {
        background-color: #333; color: white; width: 35%; padding: 20px;
        word-wrap: break-word;
    }
    .cv-photo {
        width: 120px; height: 120px; background: #ccc; border-radius: 50%;
        margin: 0 auto 20px auto; background-size: cover; background-position: center;
        border: 3px solid white;
    }
    .cv-left h3 { border-bottom: 1px solid rgba(255,255,255,0.3); padding-bottom: 5px; margin-top: 30px; font-size: 16px;}
    .cv-left p, .cv-left li { font-size: 13px; line-height: 1.4; color: #eee; list-style: none; margin-bottom: 8px;}
    .cv-left ul { padding: 0; }

    /* Colonne Droite CV */
    .cv-right { width: 65%; padding: 30px; color: #333; }
    .cv-name { font-size: 32px; font-weight: 800; text-transform: uppercase; margin: 0; line-height: 1.1;}
    .cv-job { font-size: 18px; color: #d35400; margin-top: 5px; margin-bottom: 20px; font-weight: 600;}

    .cv-section-title {
        font-size: 16px; font-weight: bold; text-transform: uppercase;
        border-bottom: 2px solid #333; padding-bottom: 5px; margin-top: 25px; margin-bottom: 15px;
        color: #333;
    }
    .cv-item { margin-bottom: 15px; border-left: 3px solid #eee; padding-left: 10px; }
    .cv-item-title { font-weight: bold; font-size: 15px; }
    .cv-item-date { font-size: 12px; color: #777; margin-bottom: 3px; font-style: italic;}
    .cv-item-desc { font-size: 14px; }

    /* Responsive Mobile */
    @media (max-width: 600px) {
        #cv-preview { flex-direction: column; }
        .cv-left, .cv-right { width: 100%; box-sizing: border-box; }
    }

    /* Cacher les contrôles à l'impression */
    @media print {
        body { background: white; padding: 0; }
        .controls { display: none; }
        #cv-preview { box-shadow: none; margin: 0; width: 100%; }
    }
</style>
</head>
<body>

<div class="controls">
    <h2>🛠 Créer votre CV</h2>

    <div class="form-group">
        <label>🎨 Choisir la couleur principale</label>
        <input type="color" id="input-color" value="#d35400" onchange="updateStyle()">
    </div>
    <div class="form-group">
        <label>🔤 Choisir la police d'écriture</label>
        <select id="input-font" onchange="updateStyle()">
            <option value="Segoe UI, sans-serif">Moderne (Sans-Serif)</option>
            <option value="Georgia, serif">Classique (Serif)</option>
            <option value="Courier New, monospace">Machine à écrire</option>
        </select>
    </div>

    <div class="form-group">
        <label>📸 Photo de profil</label>
        <input type="file" accept="image/*" onchange="loadPhoto(event)">
    </div>
    <div class="form-group">
        <input type="text" placeholder="Votre Nom Complet" onkeyup="updateText('cv-name', this.value)">
    </div>
    <div class="form-group">
        <input type="text" placeholder="Titre du poste (ex: Maître Chocolatier)" onkeyup="updateText('cv-job', this.value)">
    </div>
    <div class="form-group">
        <textarea placeholder="Brève description de profil..." onkeyup="updateText('cv-profile', this.value)"></textarea>
    </div>

    <div class="form-group">
        <label>📞 Contact & Compétences</label>
        <input type="text" placeholder="Email / Téléphone" onkeyup="updateText('cv-contact', this.value)">
        <textarea placeholder="Liste des compétences (sauter des lignes)" onkeyup="updateList('cv-skills', this.value)"></textarea>
    </div>

    <div class="form-group">
        <label>💼 Expérience & Études</label>
        <button class="btn-action" onclick="addExperience()">+ Ajouter Expérience</button>
        <button class="btn-action" onclick="addEducation()">+ Ajouter Étude</button>
        <button class="btn-action" style="background:#c0392b" onclick="resetLists()">🗑 Réinitialiser listes</button>
    </div>

    <button class="btn-action btn-print" onclick="window.print()">🖨 SAUVEGARDER EN PDF</button>
</div>

<div id="cv-preview">
    <div class="cv-left" id="left-col">
        <div class="cv-photo" id="display-photo"></div>

        <h3>CONTACT</h3>
        <p id="cv-contact">email@exemple.com<br>+32 4XX XX XX XX<br>Jeddah, KSA</p>

        <h3>COMPÉTENCES</h3>
        <ul id="cv-skills">
            <li>Chocolaterie</li>
            <li>Gestion</li>
            <li>Communication</li>
        </ul>
    </div>

    <div class="cv-right">
        <h1 class="cv-name" id="cv-name">VOTRE NOM</h1>
        <div class="cv-job" id="cv-job">TITRE DU POSTE</div>

        <div class="cv-section-title" id="title-profile">PROFIL</div>
        <p id="cv-profile">Décrivez ici votre parcours, vos passions et vos objectifs professionnels...</p>

        <div class="cv-section-title" id="title-exp">EXPÉRIENCE</div>
        <div id="experience-list">
            <div class="cv-item">
                <div class="cv-item-title">Poste occupé</div>
                <div class="cv-item-date">Date - Lieu</div>
                <div class="cv-item-desc">Description des tâches réalisées...</div>
            </div>
        </div>

        <div class="cv-section-title" id="title-edu">FORMATION</div>
        <div id="education-list">
            <div class="cv-item">
                <div class="cv-item-title">Diplôme ou Certificat</div>
                <div class="cv-item-date">Année</div>
                <div class="cv-item-desc">École ou Institut</div>
            </div>
        </div>
    </div>
</div>

<script>
    // FONCTION 1 : Mettre à jour le texte simple
    function updateText(id, value) {
        document.getElementById(id).innerText = value;
        // Si vide, on met un texte par défaut pour pas que ça disparaisse
        if(value === "") document.getElementById(id).innerText = "...";
    }

    // FONCTION 2 : Mettre à jour une liste (Compétences)
    function updateList(id, value) {
        let lines = value.split('\n');
        let html = "";
        lines.forEach(line => {
            if(line.trim() !== "") html += "<li>" + line + "</li>";
        });
        document.getElementById(id).innerHTML = html;
    }

    // FONCTION 3 : Changer couleur et police
    function updateStyle() {
        let color = document.getElementById('input-color').value;
        let font = document.getElementById('input-font').value;

        // Appliquer la couleur
        document.getElementById('left-col').style.backgroundColor = color; // Colonne gauche
        document.getElementById('cv-job').style.color = color; // Titre du job

        // Appliquer la police
        document.getElementById('cv-preview').style.fontFamily = font;
    }

    // FONCTION 4 : Charger la photo
    function loadPhoto(event) {
        let reader = new FileReader();
        reader.onload = function(){
            let output = document.getElementById('display-photo');
            output.style.backgroundImage = "url('" + reader.result + "')";
        };
        reader.readAsDataURL(event.target.files[0]);
    }

    // FONCTION 5 : Ajouter une expérience
    function addExperience() {
        let title = prompt("Titre du poste ?");
        let date = prompt("Dates et Lieu ?");
        let desc = prompt("Description rapide ?");

        if(title) {
            let newItem = `
            <div class="cv-item">
                <div class="cv-item-title">${title}</div>
                <div class="cv-item-date">${date}</div>
                <div class="cv-item-desc">${desc}</div>
            </div>`;
            document.getElementById('experience-list').innerHTML += newItem;
        }
    }

    // FONCTION 6 : Ajouter une formation
    function addEducation() {
        let title = prompt("Diplôme / École ?");
        let date = prompt("Année ?");

        if(title) {
            let newItem = `
            <div class="cv-item">
                <div class="cv-item-title">${title}</div>
                <div class="cv-item-date">${date}</div>
            </div>`;
            document.getElementById('education-list').innerHTML += newItem;
        }
    }

    // FONCTION 7 : Reset (Effacer les items par défaut)
    function resetLists() {
        if(confirm("Effacer toutes les expériences et formations ?")) {
            document.getElementById('experience-list').innerHTML = "";
            document.getElementById('education-list').innerHTML = "";
        }
    }
</script>

</body>
</html>

