                    <div className="text-[11px] leading-relaxed whitespace-pre-wrap opacity-90">{cvContact}</div>
                  </div>

                  <div>
                    <h3 className="text-sm font-bold uppercase tracking-[0.2em] border-b border-white/20 pb-2 mb-4">Skills</h3>
