              <h3 className={`text-lg mb-2 ${displayFont} font-normal`}>Neural Layouts</h3>
              <p className="text-gray-400 text-[11px] leading-relaxed font-light">
                {isAr ? 'يختار الذكاء الاصطناعي التخطيط الأمثل بناءً على بيانات تتبع العين للموظفين.' : 'AI automatically selects the optimal layout based on recruiter eye-tracking data. Dynamic sizing for holographic projection.'}
              </p>
          </div>
          <div className="p-4 transition-all duration-500">
              <Globe size={24} className="text-blue-600 mb-4" />
              <h3 className={`text-lg mb-2 ${displayFont} font-normal`}>Holo-Export</h3>
              <p className="text-gray-400 text-[11px] leading-relaxed font-light">
                {isAr ? 'قم بتصدير سيرتك الذاتية كبطاقة تفاعلية هولوغرافية للتشبيك المستقبلي.' : 'Export your CV as a holographic interactive card for high-end professional networking. Truly 50 years in the future.'}
              </p>
          </div>
          <div className="p-4 transition-all duration-500">
              <CheckCircle size={24} className="text-blue-600 mb-4" />
              <h3 className={`text-lg mb-2 ${displayFont} font-normal`}>Skill-Gap Analysis</h3>
              <p className="text-gray-400 text-[11px] leading-relaxed font-light">
                {isAr ? 'احصل على تعليقات فورية حول مهاراتك وكيف تتوافق مع اتجاهات السوق الحالية.' : 'Get real-time feedback on your professional skills and how they match trending global market demands.'}
              </p>
          </div>
      </section>

      {/* Footer Branding */}
      <footer className="py-12 bg-black border-t border-white/10 flex flex-col items-center">
         <FileText size={16} className="text-blue-600 mb-4 opacity-40" />
         <p className="text-[8px] text-gray-500 uppercase tracking-[0.5em] font-medium">AI Pro CV Master Vision™ • Master OS</p>
      </footer>
    </div>
  );
};

