}

const Navbar: React.FC<NavbarProps> = ({ onNavigate, cartCount = 0, currentView, language, translations }) => {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  const handleNavClick = (href: string) => {
    if (href === '#store') {
        onNavigate('store');
    } else if (href === '#foldable') {
        onNavigate('foldable');
    } else if (href === '#notebook') {
        onNavigate('notebook');
    } else if (href === '#holographic') {
        onNavigate('chat-web');
    } else if (href === '#fitness') {
        onNavigate('fitness');
    } else if (href === '#fintech') {
        onNavigate('fintech');
    } else if (href === '#cv-maker') {
        onNavigate('cv-maker');
    } else if (href === '#nova-tax') {
        onNavigate('nova-tax');
    } else if (href === '#telecom') {
        onNavigate('telecom');
    } else {
        onNavigate('home');
        if (href.startsWith('#')) {
             setTimeout(() => {
                const element = document.querySelector(href);
                element?.scrollIntoView({ behavior: 'smooth' });
            }, 100);
        }
    }
    setMobileMenuOpen(false);
  };

  const fontClass = language === 'ar' ? 'font-tajawal font-bold' : 'font-sans font-medium';

  return (
    <>
      <nav
