import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import ProductGrid from './components/ProductGrid';
import Footer from './components/Footer';
import ChatSupport from './components/ChatSupport';
import StorePage from './components/StorePage';
import InvestorsPage from './components/InvestorsPage';
import AboutPage from './components/AboutPage';
import S3TsChatWeb from './components/S3TsChatWeb';
import TelecomPage from './components/TelecomPage';
import FintechPage from './components/FintechPage';
import FitnessPage from './components/FitnessPage';
import CVMakerPage from './components/CVMakerPage';
import NovaTaxPage from './components/NovaTaxPage';
import FoldablePage from './components/FoldablePage';
import NotebookPage from './components/NotebookPage';
import { PRODUCTS, TRANSLATIONS } from './constants';
import { Language, AppView } from './types';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<AppView>('home');
  const [selectedProductId, setSelectedProductId] = useState<string | undefined>(undefined);
  const [cartCount, setCartCount] = useState(0);

  const [language, setLanguage] = useState<Language>('en');
  const t = TRANSLATIONS[language];

  const handleNavigate = (view: AppView, productId?: string) => {
    setCurrentView(view);
    if (productId) setSelectedProductId(productId);

    if (!['chat-web', 'telecom', 'fintech', 'fitness', 'cv-maker', 'nova-tax', 'foldable', 'notebook'].includes(view)) {
        window.scrollTo({ top: 0, behavior: 'smooth' });
    } else {
        window.scrollTo({ top: 0, behavior: 'auto' });
    }
  };

  const toggleLanguage = () => {
    setLanguage(prev => prev === 'en' ? 'ar' : 'en');
  };

  const handleAddToCart = () => {
    setCartCount(prev => prev + 1);
  };

  useEffect(() => {
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('active');
        }
      });
    }, {
      threshold: 0.1,
      rootMargin: "0px 0px -50px 0px"
    });

    setTimeout(() => {
        const elements = document.querySelectorAll('.reveal');
        elements.forEach(el => observer.observe(el));
    }, 100);

    return () => observer.disconnect();
  }, [currentView, language]); 

  const displayFont = language === 'ar' ? 'font-amiri font-bold' : 'font-display font-medium';
  const textFont = language === 'ar' ? 'font-tajawal' : 'font-sans font-light';

  if (currentView === 'chat-web') return <S3TsChatWeb onNavigate={() => setCurrentView('home')} />;
  if (currentView === 'telecom') return <TelecomPage onNavigate={handleNavigate} language={language} />;
  if (currentView === 'fintech') return <FintechPage onNavigate={handleNavigate} language={language} />;
  if (currentView === 'fitness') return <FitnessPage onNavigate={handleNavigate} language={language} />;
  if (currentView === 'cv-maker') return <CVMakerPage onNavigate={handleNavigate} language={language} />;
  if (currentView === 'nova-tax') return <NovaTaxPage onNavigate={handleNavigate} language={language} />;
  if (currentView === 'foldable') return <FoldablePage onNavigate={handleNavigate} language={language} translations={t} />;
  if (currentView === 'notebook') return <NotebookPage onNavigate={handleNavigate} language={language} translations={t} />;

  return (
    <div className={`min-h-screen bg-white text-gray-900 selection:bg-black selection:text-white ${language === 'ar' ? 'font-tajawal' : 'font-sans'}`} dir={language === 'ar' ? 'rtl' : 'ltr'}>
      <Navbar onNavigate={handleNavigate} cartCount={cartCount} currentView={currentView} language={language} translations={t} />

      <main className="pt-0">
        {currentView === 'home' && (
          <>
            <Hero onNavigate={handleNavigate} language={language} translations={t} />

            <section className="py-12 md:py-16 bg-white reveal overflow-visible relative z-0">
                <div className="max-w-[1440px] mx-auto px-6 md:px-12">
                    <div 
                        onClick={() => handleNavigate('chat-web')}
                        className="relative w-full max-w-5xl mx-auto h-[400px] md:h-[500px] bg-zinc-950 rounded-[40px] overflow-hidden group cursor-pointer shadow-2xl transition-transform duration-700 hover:scale-[1.01]"
                    >
                        <div className="absolute inset-0 opacity-20 bg-[radial-gradient(circle_at_50%_50%,_rgba(20,184,166,0.3),_transparent_70%)]"></div>
                        <div className="absolute inset-0 flex flex-col items-center justify-center p-8 text-center">
                            <div className="relative mb-10">
                                <div className="absolute inset-0 bg-teal-500 rounded-full blur-[30px] opacity-40 animate-pulse group-hover:opacity-60 transition-opacity"></div>
                                <div className="relative w-24 h-24 md:w-32 md:h-32 bg-zinc-900 rounded-[32px] border border-teal-500/30 flex items-center justify-center shadow-[0_0_40px_rgba(20,184,166,0.4)] transition-all duration-500 group-hover:shadow-[0_0_60px_rgba(20,184,166,0.6)]">
                                    <img 
                                        src="https://fit-4rce-x.s3.eu-north-1.amazonaws.com/S3Ts_chat_logo.jpg" 
                                        alt="Schat Logo" 
                                        className="w-full h-full object-cover rounded-[31px] opacity-90 group-hover:opacity-100 transition-opacity"
                                    />
                                </div>
                            </div>
                            <h3 className={`text-3xl md:text-5xl text-white mb-6 tracking-wide ${displayFont}`}>{t.tech_chat}</h3>
                            <p className={`text-gray-400 text-sm md:text-base leading-relaxed max-w-md ${textFont}`}>{t.tech_chat_desc}</p>
                            <div className="mt-10 inline-flex items-center gap-2 text-teal-400 font-bold text-[10px] uppercase tracking-[0.3em] opacity-60 group-hover:opacity-100 transition-all duration-300">
                                Launch Experience <span>→</span>
                            </div>
                        </div>
                    </div>
                </div>
            </section>

            <section id="ai" className="py-20 md:py-32 bg-black text-white reveal overflow-hidden">
                <div className="max-w-[1440px] mx-auto px-6 md:px-12">
                   <div className="flex flex-col md:flex-row items-center justify-between gap-12">
                       <div className={`flex-1 text-center ${language === 'ar' ? 'md:text-right' : 'md:text-left'} order-2 md:order-1`}>
                          <span className={`block text-blue-400 text-[10px] font-bold tracking-[0.3em] uppercase mb-4 animate-pulse ${textFont}`}>{t.bio_tag}</span>
                          <h2 className={`text-3xl md:text-5xl mb-6 ${displayFont}`}>{t.bio_title}</h2>
                          <p className={`text-gray-400 text-sm leading-relaxed tracking-wide max-w-md mx-auto ${language === 'ar' ? 'md:mr-0' : 'md:ml-0'} ${textFont}`}>{t.bio_desc}</p>
                       </div>
                       <div className="flex-1 flex justify-center md:justify-end order-1 md:order-2">
                            <img src="https://fit-4rce-x.s3.eu-north-1.amazonaws.com/S3Ts_bg_removed_facial_recognition.png" alt="S3Ts Neural Face ID" className="h-64 md:h-96 w-auto object-contain drop-shadow-2xl opacity-90"/>
                       </div>
                   </div>
                </div>
            </section>

            <section id="energy" className="py-20 md:py-32 bg-white reveal">
                <div className="max-w-[1440px] mx-auto px-6 md:px-12">
                    <div className="flex flex-col md:flex-row items-center gap-16">
                        <div className="flex-1">
                            <img src="https://fit-4rce-x.s3.eu-north-1.amazonaws.com/S3Ts_grey_rectoverso-transparent.png" alt="Solar Tech" className="w-full h-auto drop-shadow-2xl" />
                        </div>
                        <div className="flex-1">
                             <span className={`block text-gray-400 text-[10px] font-bold tracking-[0.3em] uppercase mb-4 ${textFont}`}>{t.energy_tag}</span>
                             <h2 className={`text-3xl md:text-5xl mb-8 leading-tight ${displayFont}`}>{t.energy_title}</h2>
                             <p className={`text-gray-500 text-sm leading-relaxed mb-10 ${textFont}`}>{t.energy_desc}</p>
                             <div className="grid grid-cols-2 gap-8">
                                 <div>
                                     <div className={`text-2xl text-black mb-1 ${displayFont}`}>Infinite</div>
                                     <div className={`text-[10px] text-gray-400 uppercase tracking-widest ${textFont}`}>{t.energy_lifespan}</div>
                                 </div>
                                 <div>
                                     <div className={`text-2xl text-black mb-1 ${displayFont}`}>72 Hours</div>
                                     <div className={`text-[10px] text-gray-400 uppercase tracking-widest ${textFont}`}>{t.energy_reserve}</div>
                                 </div>
                             </div>
                        </div>
                    </div>
                </div>
            </section>

            <ProductGrid 
                title={t.tech_title} 
                subtitle={t.tech_subtitle}
                products={PRODUCTS}
                onNavigate={(view) => handleNavigate(view)}
                language={language}
            />
          </>
        )}

        {currentView === 'store' && (
          <StorePage 
            onAddToCart={handleAddToCart} 
            language={language} 
            translations={t} 
            selectedProductId={selectedProductId}
          />
        )}
        {currentView === 'investors' && <InvestorsPage />}
        {currentView === 'about' && <AboutPage onNavigate={handleNavigate} language={language} translations={t} />}
      </main>

      {(['home', 'foldable', 'notebook', 'store'].includes(currentView)) && <Footer onNavigate={handleNavigate} language={language} onToggleLanguage={toggleLanguage} translations={t} />}
      <ChatSupport language={language} />
    </div>
  );
};

export default App;

