import React, { useState, useEffect } from 'react';
import { Check, Shield, Zap, X, ChevronRight, ArrowLeft } from 'lucide-react';
import { Language, Product } from '../types';
import { PRODUCTS } from '../constants';

interface StorePageProps {
  onAddToCart: () => void;
  language?: Language;
  translations?: any;
  selectedProductId?: string;
}

const VARIANTS = [
    { id: 'grey', name: 'Titanium Grey', color: 'bg-gray-300', image: 'https://fit-4rce-x.s3.eu-north-1.amazonaws.com/S3Ts_grey_rectoverso-transparent.png' },
    { id: 'black', name: 'Midnight Black', color: 'bg-zinc-900', image: 'https://fit-4rce-x.s3.eu-north-1.amazonaws.com/S3Ts_black_rectoverso-transparent.png' },
    { id: 'blue', name: 'Sapphire Blue', color: 'bg-blue-900', image: 'https://fit-4rce-x.s3.eu-north-1.amazonaws.com/S3Ts_blue_rectoverso-transparent.png' },
    { id: 'rose', name: 'Rose Gold', color: 'bg-rose-300', image: 'https://fit-4rce-x.s3.eu-north-1.amazonaws.com/S3Ts_gd-rose_rectoverso-transparent.png' },
];

const StorePage: React.FC<StorePageProps> = ({ onAddToCart, language = 'en', translations, selectedProductId }) => {
  const t = translations || {};

  const [currentProduct, setCurrentProduct] = useState<Product | null>(
    selectedProductId ? PRODUCTS.find(p => p.id === selectedProductId) || null : null
  );

  const [selectedVariant, setSelectedVariant] = useState(VARIANTS[0]);
  const [showSpecs, setShowSpecs] = useState(false);

  useEffect(() => {
    if (selectedProductId) {
      const p = PRODUCTS.find(prod => prod.id === selectedProductId);
      if (p) setCurrentProduct(p);
    }
  }, [selectedProductId]);

  const displayFont = language === 'ar' ? 'font-amiri font-bold' : 'font-display font-medium';
  const textFont = language === 'ar' ? 'font-tajawal' : 'font-sans font-light';

  // --- GRID VIEW (Catalog) ---
  if (!currentProduct) {
    return (
      <div className={`pt-8 pb-32 bg-white min-h-screen ${textFont}`} dir={language === 'ar' ? 'rtl' : 'ltr'}>
        <div className="max-w-[1440px] mx-auto px-6 md:px-12">
            <div className="text-center mb-16">
                <h1 className={`text-3xl md:text-5xl mb-4 ${displayFont}`}>{t.store_crumb}</h1>
                <p className="text-gray-400 uppercase tracking-widest text-[10px]">{t.store_tagline}</p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-12">
                {PRODUCTS.map((product) => (
                    <div 
                        key={product.id} 
                        onClick={() => setCurrentProduct(product)}
                        className="group cursor-pointer border border-gray-50 p-8 rounded-[40px] hover:shadow-2xl transition-all duration-500 bg-white flex flex-col items-center"
                    >
                        <div className="aspect-square w-full mb-8 flex items-center justify-center overflow-hidden">
                            <img src={product.image} alt={product.name} className="w-[85%] h-auto object-contain transform group-hover:scale-105 transition-transform duration-700" />
                        </div>
                        <h3 className={`text-xl mb-1 ${displayFont}`}>{product.name}</h3>
                        <p className="text-[10px] text-gray-400 uppercase tracking-widest mb-6">{product.tagline}</p>
                        <div className="text-lg font-bold text-black mb-6">{product.price}</div>
                        <button className="px-8 py-3 bg-black text-white rounded-full text-[10px] font-bold uppercase tracking-widest group-hover:bg-teal-600 transition-colors">
                            Configure
                        </button>
                    </div>
                ))}
            </div>
        </div>
      </div>
    );
  }

  // --- DETAIL VIEW (Configurator) ---
  return (
    <div className={`pb-20 bg-white min-h-screen animate-fade-in relative ${textFont}`} dir={language === 'ar' ? 'rtl' : 'ltr'}>

      {/* Back to Catalog */}
      <div className="max-w-[1200px] mx-auto px-6 md:px-12 pt-8">
        <button 
            onClick={() => setCurrentProduct(null)}
            className="flex items-center gap-2 text-[10px] font-bold uppercase tracking-widest text-gray-400 hover:text-black transition-colors"
        >
            <ArrowLeft size={14} className={language === 'ar' ? 'rotate-180' : ''} />
            Back to Catalog
        </button>
      </div>

      <div className="max-w-[1200px] mx-auto px-6 md:px-12 py-12">
        <div className="flex flex-col md:flex-row gap-12 md:gap-24">

            {/* Left: Product Image */}
            <div className="flex-1">
                <div className="w-full relative flex items-center justify-center bg-gray-50 rounded-[60px] aspect-[4/5] overflow-hidden shadow-sm">
                    <img 
                        src={currentProduct.id === 'pro3' ? selectedVariant.image : currentProduct.image} 
                        alt={currentProduct.name} 
                        className="w-[85%] h-auto object-contain drop-shadow-2xl"
                    />
                </div>
            </div>

            {/* Right: Product UI */}
            <div className="flex-1">
                <div className="border-b border-gray-100 pb-8 mb-8">
                    <h1 className={`text-4xl md:text-6xl text-gray-900 mb-4 ${displayFont}`}>{currentProduct.name}</h1>
                    <p className="text-gray-400 text-xs tracking-widest uppercase mb-8">{currentProduct.tagline}</p>
                    <div className="text-3xl font-bold text-black">{currentProduct.price}</div>
                    <div className="flex items-center gap-2 text-green-600 text-[10px] font-bold mt-6 uppercase tracking-widest">
                        <Check size={12} /> {t.store_stock}
                    </div>
                </div>

                {/* Colors (Pro 3.0 Only) */}
                {currentProduct.id === 'pro3' && (
                  <div className="mb-12">
                      <label className="block text-[10px] font-bold uppercase tracking-widest mb-4">
                          {t.store_finish}: <span className="text-gray-900">{selectedVariant.name}</span>
                      </label>
                      <div className="flex gap-4">
                          {VARIANTS.map((v) => (
                              <button 
                                  key={v.id}
                                  onClick={() => setSelectedVariant(v)}
                                  className={`w-10 h-10 rounded-full border-2 ${v.color} ${selectedVariant.id === v.id ? 'ring-2 ring-offset-2 ring-black border-transparent' : 'border-transparent hover:scale-110'} transition-all`}
                              />
                          ))}
                      </div>
                  </div>
                )}

                <div className="mb-12">
                    <label className="block text-[10px] font-bold uppercase tracking-widest mb-4">{t.store_core}</label>
                    <div className="p-4 bg-black text-white rounded-2xl flex justify-between items-center border border-black shadow-lg">
                        <span className="text-xs font-bold uppercase tracking-widest">{t.store_core_name}</span>
                        <span className="text-[10px] opacity-60 font-bold">{t.store_included}</span>
                    </div>
                </div>

                <button 
                    onClick={onAddToCart}
                    className="w-full bg-black text-white py-6 rounded-2xl text-xs font-bold uppercase tracking-[0.3em] hover:bg-zinc-800 transition-all shadow-xl mb-8"
                >
                    {t.store_add}
                </button>

                <button 
                    onClick={() => setShowSpecs(true)}
                    className="flex items-center gap-2 text-[10px] font-bold uppercase tracking-widest text-black hover:text-gray-500 transition-colors"
                >
                    {t.store_view_specs} <ChevronRight size={14} className={language === 'ar' ? 'rotate-180' : ''} />
                </button>

                {/* Badges */}
                <div className="mt-16 grid grid-cols-2 gap-8 border-t border-gray-100 pt-12">
                    <div className="flex items-start gap-4">
                        <Shield size={20} className="text-black" />
                        <div>
                            <p className="text-[10px] font-bold uppercase tracking-widest mb-1">{t.store_warranty_title}</p>
                            <p className="text-[10px] text-gray-500">{t.store_warranty_desc}</p>
                        </div>
                    </div>
                    <div className="flex items-start gap-4">
                        <Zap size={20} className="text-black" />
                        <div>
                            <p className="text-[10px] font-bold uppercase tracking-widest mb-1">{t.store_solar_title}</p>
                            <p className="text-[10px] text-gray-500">{t.store_solar_desc}</p>
                        </div>
                    </div>
                </div>
            </div>
        </div>
      </div>

      {/* Specifications Drawer */}
      <div className={`fixed inset-0 z-[60] transition-opacity duration-500 ${showSpecs ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`}>
          <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={() => setShowSpecs(false)}></div>
