import React, { useState, useEffect } from 'react';
import { Check, Shield, Zap, X, ChevronRight, ArrowLeft, ShoppingBag } from 'lucide-react';
import { Language, Product } from '../types';
import { PRODUCTS } from '../constants';

interface StorePageProps {
  onAddToCart: () => void;
  language?: Language;
  translations?: any;
  selectedProductId?: string;
  onBackToCatalog?: () => void;
}

const VARIANTS = [
    { id: 'grey', name: 'Titanium Grey', color: 'bg-gray-300', image: 'https://fit-4rce-x.s3.eu-north-1.amazonaws.com/S3Ts_grey_rectoverso-transparent.png' },
    { id: 'black', name: 'Midnight Black', color: 'bg-zinc-900', image: 'https://fit-4rce-x.s3.eu-north-1.amazonaws.com/S3Ts_black_rectoverso-transparent.png' },
    { id: 'blue', name: 'Sapphire Blue', color: 'bg-blue-900', image: 'https://fit-4rce-x.s3.eu-north-1.amazonaws.com/S3Ts_blue_rectoverso-transparent.png' },
    { id: 'rose', name: 'Rose Gold', color: 'bg-rose-300', image: 'https://fit-4rce-x.s3.eu-north-1.amazonaws.com/S3Ts_gd-rose_rectoverso-transparent.png' },
];

const StorePage: React.FC<StorePageProps> = ({ onAddToCart, language = 'en', translations, selectedProductId, onBackToCatalog }) => {
  const t = translations || {};

  const [currentProduct, setCurrentProduct] = useState<Product | null>(null);
  const [selectedVariant, setSelectedVariant] = useState(VARIANTS[0]);
  const [showSpecs, setShowSpecs] = useState(false);
  const [addedToCartAnim, setAddedToCartAnim] = useState(false);

  // Synchronisation avec les props
  useEffect(() => {
    if (selectedProductId) {
      const p = PRODUCTS.find(prod => prod.id === selectedProductId);
      if (p) setCurrentProduct(p);
    } else {
      setCurrentProduct(null);
    }
  }, [selectedProductId]);

  const handleBack = () => {
    if (onBackToCatalog) {
      onBackToCatalog();
    }
    setCurrentProduct(null);
  };

  const handleAddToCart = () => {
    onAddToCart();
    setAddedToCartAnim(true);
    setTimeout(() => setAddedToCartAnim(false), 2000);
  };

  const displayFont = language === 'ar' ? 'font-amiri font-bold' : 'font-display font-medium';
  const textFont = language === 'ar' ? 'font-tajawal' : 'font-sans font-light';

  // --- CATALOG VIEW ---
  if (!currentProduct) {
    return (
      <div className={`pt-12 pb-32 bg-white min-h-screen ${textFont} animate-fade-in`} dir={language === 'ar' ? 'rtl' : 'ltr'}>
        <div className="max-w-[1440px] mx-auto px-6 md:px-12">
            <div className="text-center mb-16">
                <h1 className={`text-4xl md:text-6xl mb-4 ${displayFont}`}>{t.store_crumb}</h1>
                <p className="text-gray-400 uppercase tracking-widest text-xs">{t.store_tagline}</p>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-12">
                {PRODUCTS.map((product) => (
                    <div 
                        key={product.id} 
                        onClick={() => setCurrentProduct(product)}
                        className="group cursor-pointer border border-gray-100 p-8 rounded-[40px] hover:shadow-2xl transition-all duration-500 bg-white flex flex-col items-center"
                    >
                        <div className="aspect-square w-full mb-8 flex items-center justify-center overflow-hidden">
                            <img src={product.image} alt={product.name} className="w-[85%] h-auto object-contain transform group-hover:scale-105 transition-transform duration-700" />
                        </div>
                        <h3 className={`text-2xl mb-1 ${displayFont}`}>{product.name}</h3>
                        <p className="text-xs text-gray-400 uppercase tracking-widest mb-6">{product.tagline}</p>
                        <div className="text-xl font-bold text-black mb-6">{product.price}</div>
                        <button className="px-10 py-4 bg-black text-white rounded-full text-xs font-bold uppercase tracking-widest group-hover:bg-teal-600 transition-colors">
                            Configure
                        </button>
                    </div>
                ))}
            </div>
        </div>
      </div>
    );
  }

  // --- PRODUCT DETAIL VIEW ---
  return (
    <div className={`pb-20 bg-white min-h-screen animate-fade-in relative ${textFont}`} dir={language === 'ar' ? 'rtl' : 'ltr'}>

      {/* Breadcrumb Navigation */}
      <div className="max-w-[1200px] mx-auto px-6 md:px-12 pt-8">
        <button 
            onClick={handleBack}
            className="group flex items-center gap-2 text-xs font-bold uppercase tracking-widest text-gray-400 hover:text-black transition-colors"
        >
            <ArrowLeft size={16} className={`${language === 'ar' ? 'rotate-180' : ''} group-hover:-translate-x-1 transition-transform`} />
            {language === 'ar' ? 'العودة إلى المتجر' : 'Back to Catalog'}
        </button>
      </div>

      <div className="max-w-[1200px] mx-auto px-6 md:px-12 py-12">
        <div className="flex flex-col md:flex-row gap-12 md:gap-24">

            {/* Left: Interactive Image */}
            <div className="flex-1">
                <div className="w-full relative flex items-center justify-center bg-gray-50 rounded-[60px] aspect-[4/5] overflow-hidden shadow-sm">
                    <img 
                        src={currentProduct.id === 'pro3' ? selectedVariant.image : currentProduct.image} 
                        alt={currentProduct.name} 
                        className="w-[85%] h-auto object-contain drop-shadow-2xl animate-float"
                    />
                </div>
            </div>

            {/* Right: Customization UI */}
            <div className="flex-1">
                <div className="border-b border-gray-100 pb-8 mb-8">
                    <h1 className={`text-4xl md:text-6xl text-gray-900 mb-4 ${displayFont}`}>{currentProduct.name}</h1>
                    <p className="text-gray-400 text-sm tracking-widest uppercase mb-8">{currentProduct.tagline}</p>
                    <div className="text-4xl font-bold text-black">{currentProduct.price}</div>
                    <div className="flex items-center gap-2 text-green-600 text-xs font-bold mt-6 uppercase tracking-widest">
                        <Check size={14} /> {t.store_stock}
                    </div>
                </div>

                {/* Variant Selector (Only for Pro 3.0) */}
                {currentProduct.id === 'pro3' && (
                  <div className="mb-12">
                      <label className="block text-xs font-bold uppercase tracking-widest mb-4">
                          {t.store_finish}: <span className="text-gray-900">{selectedVariant.name}</span>
                      </label>
                      <div className="flex gap-4">
                          {VARIANTS.map((v) => (
                              <button 
                                  key={v.id}
                                  onClick={() => setSelectedVariant(v)}
                                  className={`w-12 h-12 rounded-full border-2 ${v.color} ${selectedVariant.id === v.id ? 'ring-2 ring-offset-2 ring-black border-transparent' : 'border-transparent hover:scale-110'} transition-all`}
                                  title={v.name}
                              />
                          ))}
                      </div>
                  </div>
                )}

                <div className="mb-12">
                    <label className="block text-xs font-bold uppercase tracking-widest mb-4">{t.store_core}</label>
                    <div className="p-5 bg-black text-white rounded-2xl flex justify-between items-center border border-black shadow-lg">
                        <span className="text-sm font-bold uppercase tracking-widest">{t.store_core_name}</span>
                        <span className="text-xs opacity-60 font-bold">{t.store_included}</span>
                    </div>
                </div>

                <div className="flex flex-col gap-4 mb-10">
                    <button 
                        onClick={handleAddToCart}
                        className={`w-full py-6 rounded-2xl text-xs font-bold uppercase tracking-[0.3em] transition-all shadow-xl flex items-center justify-center gap-3 ${addedToCartAnim ? 'bg-green-600 text-white' : 'bg-black text-white hover:bg-zinc-800'}`}
                    >
                        {addedToCartAnim ? <Check size={16} /> : <ShoppingBag size={16} />}
                        {addedToCartAnim ? (language === 'ar' ? 'تمت الإضافة' : 'Added to Bag') : t.store_add}
                    </button>
                    <button 
                        onClick={() => setShowSpecs(true)}
                        className="w-full border border-gray-200 py-6 rounded-2xl text-xs font-bold uppercase tracking-[0.3em] flex items-center justify-center gap-2 hover:bg-gray-50 transition-colors"
                    >
                        {t.store_view_specs} <ChevronRight size={16} className={language === 'ar' ? 'rotate-180' : ''} />
                    </button>
                </div>

                {/* Quick Specs Badges */}
                <div className="grid grid-cols-2 gap-8 border-t border-gray-100 pt-12">
                    <div className="flex items-start gap-4">
                        <Shield size={24} className="text-black shrink-0" />
                        <div>
                            <p className="text-xs font-bold uppercase tracking-widest mb-1">{t.store_warranty_title}</p>
                            <p className="text-xs text-gray-500">{t.store_warranty_desc}</p>
                        </div>
                    </div>
                    <div className="flex items-start gap-4">
                        <Zap size={24} className="text-black shrink-0" />
                        <div>
                            <p className="text-xs font-bold uppercase tracking-widest mb-1">{t.store_solar_title}</p>
                            <p className="text-xs text-gray-500">{t.store_solar_desc}</p>
                        </div>
                    </div>
                </div>
            </div>
        </div>
      </div>

      {/* TECHNICAL SPECIFICATIONS MODAL */}
      <div className={`fixed inset-0 z-[100] transition-all duration-500 ease-in-out ${showSpecs ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`}>
          <div className="absolute inset-0 bg-black/70 backdrop-blur-md" onClick={() => setShowSpecs(false)}></div>
          <div className={`absolute top-0 right-0 h-full w-full md:w-[600px] bg-white shadow-2xl transition-transform duration-700 ease-[cubic-bezier(0.16,1,0.3,1)] flex flex-col ${showSpecs ? 'translate-x-0' : 'translate-x-full'}`}>

              <div className="p-8 border-b border-gray-100 flex justify-between items-center sticky top-0 bg-white z-10">
                  <div>
                      <h3 className={`text-3xl ${displayFont}`}>{currentProduct.name}</h3>
                      <p className="text-xs text-gray-400 uppercase tracking-widest mt-1">Full Technical Analysis</p>
                  </div>
                  <button onClick={() => setShowSpecs(false)} className="p-3 hover:bg-gray-100 rounded-full transition-colors">
                      <X size={28} />
                  </button>
              </div>

              <div className="flex-1 overflow-y-auto p-8 custom-scrollbar">
                  <div className="space-y-16">

                      <div className="reveal active">
                          <h4 className="text-[10px] font-bold uppercase tracking-[0.4em] text-blue-600 mb-8">Hardware Architecture</h4>
                          <div className="space-y-8">
                              {currentProduct.specs?.map((spec, i) => (
                                  <div key={i} className="flex items-start gap-6 group">
                                      <div className="w-2 h-2 rounded-full bg-black mt-2 shrink-0 group-hover:scale-150 transition-transform"></div>
                                      <div>
                                          <p className="text-lg text-gray-900 leading-tight font-light mb-1">{spec}</p>
                                          <p className="text-xs text-gray-400">Optimized for Quantum Neural Processing</p>
                                      </div>
                                  </div>
                              ))}
                          </div>
                      </div>

                      <div className="bg-gray-50 p-10 rounded-[40px] reveal active">
                          <h4 className="text-[10px] font-bold uppercase tracking-[0.4em] text-gray-500 mb-6">The 3 Zeros Standard</h4>
                          <div className="space-y-4">
                              <p className="text-sm text-gray-800 leading-relaxed italic">
                                  "This device is engineered to eliminate the necessity for toxic lithium mining. Every component is sourced ethically, ensuring a supply chain free from human exploitation."
                              </p>
                              <div className="pt-4 flex gap-4">
                                  <div className="w-8 h-8 rounded-full bg-white flex items-center justify-center border border-gray-100"><Shield size={14} /></div>
                                  <div className="w-8 h-8 rounded-full bg-white flex items-center justify-center border border-gray-100"><Zap size={14} /></div>
                                  <div className="w-8 h-8 rounded-full bg-white flex items-center justify-center border border-gray-100"><Check size={14} /></div>
                              </div>
                          </div>
                      </div>

                      <div className="pb-12 text-center">
                           <button 
                             onClick={handleAddToCart}
                             className="w-full py-6 bg-black text-white rounded-2xl text-xs font-bold uppercase tracking-[0.4em] shadow-xl hover:bg-teal-600 transition-colors"
                           >
                               Confirm Configuration
                           </button>
                      </div>

                  </div>
              </div>
          </div>
      </div>
    </div>
  );
