import React, { useState } from 'react';
import { Search, ShoppingBag, User, Menu, X } from 'lucide-react';
import { NAV_ITEMS } from '../constants';
import { Language, AppView } from '../types';

interface NavbarProps {
  onNavigate: (view: AppView, productId?: string) => void;
  cartCount?: number;
  currentView: string;
  language: Language;
  translations: any;
}

const Navbar: React.FC<NavbarProps> = ({ onNavigate, cartCount = 0, currentView, language, translations }) => {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  const handleNavClick = (href: string) => {
    if (href === '#store') {
        onNavigate('store', undefined); // Réinitialise vers le catalogue complet
    } else if (href === '#home') {
        onNavigate('home');
    } else if (href === '#foldable') {
        onNavigate('store', 'foldable'); // Directement vers SUMĀMAH F
    } else if (href === '#notebook') {
        onNavigate('store', 'notebook'); // Directement vers SUMĀMAH Aura
    } else if (href === '#holographic') {
        onNavigate('chat-web');
    } else if (href === '#fitness') {
        onNavigate('fitness');
    } else if (href === '#fintech') {
        onNavigate('fintech');
    } else if (href === '#cv-maker') {
        onNavigate('cv-maker');
    } else if (href === '#nova-tax') {
        onNavigate('nova-tax');
    } else if (href === '#telecom') {
        onNavigate('telecom');
    } else {
        onNavigate('home');
        if (href.startsWith('#')) {
             setTimeout(() => {
                const element = document.querySelector(href);
                element?.scrollIntoView({ behavior: 'smooth' });
            }, 100);
        }
    }
    setMobileMenuOpen(false);
  };

  const fontClass = language === 'ar' ? 'font-tajawal font-bold' : 'font-sans font-medium';

  return (
    <>
      <nav
        className="fixed top-0 w-full z-50 bg-white shadow-sm text-gray-900 transition-all duration-300 h-16 md:h-24 flex items-center"
