import React, { useState } from 'react';
import { Search, ShoppingBag, User, Menu, X } from 'lucide-react';
import { NAV_ITEMS } from '../constants';
import { Language, AppView } from '../types';

interface NavbarProps {
  onNavigate: (view: AppView, productId?: string) => void;
  cartCount?: number;
  currentView: string;
  language: Language;
  translations: any;
  onOpenCart: () => void;
}

const Navbar: React.FC<NavbarProps> = ({ onNavigate, cartCount = 0, currentView, language, translations, onOpenCart }) => {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  const handleNavClick = (href: string) => {
    if (href === '#store') {
        onNavigate('store', undefined);
    } else if (href === '#home') {
        onNavigate('home');
    } else if (href === '#foldable') {
        onNavigate('store', 'foldable');
    } else if (href === '#notebook') {
        onNavigate('store', 'notebook');
    } else if (href === '#holographic') {
        onNavigate('chat-web');
    } else if (href === '#fitness') {
        onNavigate('fitness');
    } else if (href === '#fintech') {
        onNavigate('fintech');
    } else if (href === '#cv-maker') {
        onNavigate('cv-maker');
    } else if (href === '#nova-tax') {
        onNavigate('nova-tax');
    } else if (href === '#telecom') {
        onNavigate('telecom');
    } else {
        onNavigate('home');
        if (href.startsWith('#')) {
             setTimeout(() => {
                const element = document.querySelector(href);
                element?.scrollIntoView({ behavior: 'smooth' });
            }, 100);
        }
    }
    setMobileMenuOpen(false);
  };

  const fontClass = language === 'ar' ? 'font-tajawal font-bold' : 'font-sans font-medium';

  return (
    <>
      <nav
        className="fixed top-0 w-full z-50 bg-white/95 backdrop-blur-md shadow-sm text-gray-900 transition-all duration-300 h-16 md:h-24 flex items-center"
        dir={language === 'ar' ? 'rtl' : 'ltr'}
      >
        <div className="max-w-[1440px] mx-auto px-6 md:px-12 relative flex items-center justify-between w-full h-full">

          <div className="hidden lg:flex items-center gap-6 flex-1">
            {NAV_ITEMS.slice(0, 5).map((item) => (
              <button
                key={item.label}
                onClick={() => handleNavClick(item.href)}
                className={`text-[9px] xl:text-[10px] tracking-widest uppercase hover:text-gray-500 transition-colors relative group whitespace-nowrap ${fontClass}`}
              >
                {translations[item.label]}
                <span className={`absolute -bottom-2 left-0 w-full h-[1px] bg-black scale-x-0 group-hover:scale-x-100 transition-transform duration-300 ${language === 'ar' ? 'origin-right' : 'origin-left'}`}></span>
              </button>
            ))}
          </div>

          <button 
            className="lg:hidden text-black flex-1 flex justify-start z-50"
            onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
          >
            {mobileMenuOpen ? <X size={20} /> : <Menu size={20} />}
          </button>

          <div className="flex-0 flex justify-center absolute left-1/2 transform -translate-x-1/2 z-50">
            <button onClick={() => onNavigate('home')} className="flex flex-col items-center group">
               <img 
                  src="https://fit-4rce-x.s3.eu-north-1.amazonaws.com/SUM%C4%80MAH_whitelogo_white_bg.jpg" 
                  alt="Sumāmah Logo" 
                  className="h-14 md:h-20 w-auto transition-transform duration-500 group-hover:scale-105"
               />
            </button>
          </div>

          <div className="hidden lg:flex items-center justify-end gap-6 flex-1">
             {NAV_ITEMS.slice(5).map((item) => (
              <button
                key={item.label}
                onClick={() => handleNavClick(item.href)}
                className={`text-[9px] xl:text-[10px] tracking-widest uppercase hover:text-gray-500 transition-colors relative group whitespace-nowrap ${fontClass}`}
              >
                {translations[item.label]}
                <span className={`absolute -bottom-2 left-0 w-full h-[1px] bg-black scale-x-0 group-hover:scale-x-100 transition-transform duration-300 ${language === 'ar' ? 'origin-right' : 'origin-left'}`}></span>
              </button>
            ))}
            <div className={`flex items-center gap-6 ${language === 'ar' ? 'border-r pr-6' : 'border-l pl-6'} border-gray-300/30`}>
                <button className="hover:opacity-60 transition-opacity">
                  <Search size={18} strokeWidth={1} />
                </button>
                <button onClick={onOpenCart} className="hover:opacity-60 transition-opacity relative group">
                  <ShoppingBag size={18} strokeWidth={1} className="group-hover:scale-110 transition-transform" />
                  {cartCount > 0 && (
                      <span className="absolute -top-1.5 -right-1.5 w-4 h-4 bg-teal-500 text-white text-[8px] font-bold rounded-full flex items-center justify-center animate-bounce">
                          {cartCount}
                      </span>
                  )}
                </button>
                <button className="hover:opacity-60 transition-opacity">
                  <User size={18} strokeWidth={1} />
                </button>
            </div>
          </div>

           <div className="flex lg:hidden items-center justify-end gap-4 flex-1 z-50">
               <button onClick={onOpenCart} className="hover:opacity-60 relative">
                  <ShoppingBag size={20} strokeWidth={1} />
                  {cartCount > 0 && (
                      <span className="absolute -top-1 -right-1 w-3 h-3 bg-teal-500 rounded-full"></span>
                  )}
                </button>
           </div>
        </div>
      </nav>

      <div className={`fixed inset-0 z-40 lg:hidden pointer-events-none`} dir={language === 'ar' ? 'rtl' : 'ltr'}>
        <div 
            className={`absolute inset-0 bg-black/40 backdrop-blur-sm transition-opacity duration-500 ${mobileMenuOpen ? 'opacity-100 pointer-events-auto' : 'opacity-0'}`} 
            onClick={() => setMobileMenuOpen(false)}
        />
        <div 
            className={`absolute top-0 ${language === 'ar' ? 'right-0 border-l' : 'left-0 border-r'} h-full w-[280px] bg-white shadow-2xl transform transition-transform duration-500 ease-out flex flex-col pt-24 px-8 pointer-events-auto border-gray-100 ${mobileMenuOpen ? 'translate-x-0' : (language === 'ar' ? 'translate-x-full' : '-translate-x-full')}`}
        >
          <div className="flex-1 overflow-y-auto py-8">
            <div className="flex flex-col gap-6">
              {NAV_ITEMS.map((item) => (
                  <button
                    key={item.label}
                    onClick={() => handleNavClick(item.href)}
                    className={`text-xs tracking-[0.25em] uppercase text-gray-900 text-left hover:text-gray-500 transition-colors ${fontClass}`}
                  >
                    {translations[item.label]}
                  </button>
              ))}
            </div>
          </div>
        </div>
      </div>
    </>
  );
};

export default Navbar;

import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import ProductGrid from './components/ProductGrid';
import Footer from './components/Footer';
import ChatSupport from './components/ChatSupport';
import StorePage from './components/StorePage';
import InvestorsPage from './components/InvestorsPage';
import AboutPage from './components/AboutPage';
import S3TsChatWeb from './components/S3TsChatWeb';
import TelecomPage from './components/TelecomPage';
import FintechPage from './components/FintechPage';
import FitnessPage from './components/FitnessPage';
import CVMakerPage from './components/CVMakerPage';
import NovaTaxPage from './components/NovaTaxPage';
import FoldablePage from './components/FoldablePage';
import NotebookPage from './components/NotebookPage';
import { PRODUCTS, TRANSLATIONS } from './constants';
import { Language, AppView } from './types';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<AppView>('home');
  const [selectedProductId, setSelectedProductId] = useState<string | undefined>(undefined);
  const [cartCount, setCartCount] = useState(0);

  const [language, setLanguage] = useState<Language>('en');
  const t = TRANSLATIONS[language];

  // Fonction de navigation corrigée pour réinitialiser le produit si on clique sur "Store"
  const handleNavigate = (view: AppView, productId?: string) => {
    setCurrentView(view);
    setSelectedProductId(productId);

    // Scroll au top lors du changement de vue
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const toggleLanguage = () => {
    setLanguage(prev => prev === 'en' ? 'ar' : 'en');
  };

  const handleAddToCart = () => {
    setCartCount(prev => prev + 1);
  };

  useEffect(() => {
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('active');
        }
      });
    }, {
      threshold: 0.1,
      rootMargin: "0px 0px -50px 0px"
    });

    setTimeout(() => {
        const elements = document.querySelectorAll('.reveal');
        elements.forEach(el => observer.observe(el));
    }, 100);

    return () => observer.disconnect();
  }, [currentView, language]); 

  const displayFont = language === 'ar' ? 'font-amiri font-bold' : 'font-display font-medium';
  const textFont = language === 'ar' ? 'font-tajawal' : 'font-sans font-light';

  if (currentView === 'chat-web') return <S3TsChatWeb onNavigate={() => setCurrentView('home')} />;
  if (currentView === 'telecom') return <TelecomPage onNavigate={handleNavigate} language={language} />;
  if (currentView === 'fintech') return <FintechPage onNavigate={handleNavigate} language={language} />;
  if (currentView === 'fitness') return <FitnessPage onNavigate={handleNavigate} language={language} />;
  if (currentView === 'cv-maker') return <CVMakerPage onNavigate={handleNavigate} language={language} />;
  if (currentView === 'nova-tax') return <NovaTaxPage onNavigate={handleNavigate} language={language} />;
  if (currentView === 'foldable') return <FoldablePage onNavigate={handleNavigate} language={language} translations={t} />;
  if (currentView === 'notebook') return <NotebookPage onNavigate={handleNavigate} language={language} translations={t} />;

  return (
    <div className={`min-h-screen bg-white text-gray-900 selection:bg-black selection:text-white ${language === 'ar' ? 'font-tajawal' : 'font-sans'}`} dir={language === 'ar' ? 'rtl' : 'ltr'}>
      <Navbar onNavigate={handleNavigate} cartCount={cartCount} currentView={currentView} language={language} translations={t} />

      <main className="pt-0">
        {currentView === 'home' && (
          <>
            <Hero onNavigate={handleNavigate} language={language} translations={t} />

            <section className="py-12 md:py-16 bg-white reveal">
                <div className="max-w-[1440px] mx-auto px-6 md:px-12">
                    <div 
                        onClick={() => handleNavigate('chat-web')}
                        className="relative w-full max-w-5xl mx-auto h-[400px] md:h-[500px] bg-zinc-950 rounded-[40px] overflow-hidden group cursor-pointer shadow-2xl transition-transform duration-700 hover:scale-[1.01]"
                    >
                        <div className="absolute inset-0 opacity-20 bg-[radial-gradient(circle_at_50%_50%,_rgba(20,184,166,0.3),_transparent_70%)]"></div>
                        <div className="absolute inset-0 flex flex-col items-center justify-center p-8 text-center">
                            <div className="relative mb-10">
                                <div className="absolute inset-0 bg-teal-500 rounded-full blur-[30px] opacity-40 animate-pulse group-hover:opacity-60 transition-opacity"></div>
                                <div className="relative w-24 h-24 md:w-32 md:h-32 bg-zinc-900 rounded-[32px] border border-teal-500/30 flex items-center justify-center">
                                    <img 
                                        src="https://fit-4rce-x.s3.eu-north-1.amazonaws.com/S3Ts_chat_logo.jpg" 
                                        alt="Schat Logo" 
                                        className="w-full h-full object-cover rounded-[31px]"
                                    />
