import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/Hero';
import ProductGrid from './components/ProductGrid';
import Footer from './components/Footer';
import ChatSupport from './components/ChatSupport';
import StorePage from './components/StorePage';
import CartPage from './components/CartPage';
import InvestorsPage from './components/InvestorsPage';
import AboutPage from './components/AboutPage';
import S3TsChatWeb from './components/S3TsChatWeb';
import TelecomPage from './components/TelecomPage';
import FintechPage from './components/FintechPage';
import FitnessPage from './components/FitnessPage';
import CVMakerPage from './components/CVMakerPage';
import NovaTaxPage from './components/NovaTaxPage';
import FoldablePage from './components/FoldablePage';
import NotebookPage from './components/NotebookPage';
import { PRODUCTS, TRANSLATIONS } from './constants';
import { Language, AppView, CartItem, Product } from './types';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<AppView>('home');
  const [selectedProductId, setSelectedProductId] = useState<string | undefined>(undefined);
  const [cartItems, setCartItems] = useState<CartItem[]>([]);

  const [language, setLanguage] = useState<Language>('en');
  const t = TRANSLATIONS[language];

  const handleNavigate = (view: AppView, productId?: string) => {
    setCurrentView(view);
    setSelectedProductId(productId);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleAddToCart = (product: Product) => {
    setCartItems(prev => {
      const existing = prev.find(item => item.id === product.id);
      if (existing) {
        return prev.map(item => item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item);
      }
      return [...prev, { ...product, quantity: 1 }];
    });
    setCurrentView('cart');
  };

  const handleUpdateQuantity = (id: string, delta: number) => {
    setCartItems(prev => prev.map(item => {
      if (item.id === id) {
        const newQty = Math.max(1, item.quantity + delta);
        return { ...item, quantity: newQty };
      }
      return item;
    }));
  };

  const handleRemoveFromCart = (id: string) => {
    setCartItems(prev => prev.filter(item => item.id !== id));
  };

  const toggleLanguage = () => {
    setLanguage(prev => prev === 'en' ? 'ar' : 'en');
  };

  useEffect(() => {
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('active');
        }
      });
    }, {
      threshold: 0.1,
      rootMargin: "0px 0px -50px 0px"
    });

    setTimeout(() => {
        const elements = document.querySelectorAll('.reveal');
        elements.forEach(el => observer.observe(el));
    }, 100);

    return () => observer.disconnect();
  }, [currentView, language]); 

  // Page spéciale Chat sans Navbar
  if (currentView === 'chat-web') return <S3TsChatWeb onNavigate={() => setCurrentView('home')} />;

  const renderView = () => {
    switch (currentView) {
      case 'home':
        return (
          <>
            <Hero onNavigate={handleNavigate} language={language} translations={t} />
            <section id="ai" className="py-20 md:py-32 bg-black text-white reveal overflow-hidden">
                <div className="max-w-[1440px] mx-auto px-6 md:px-12">
                   <div className="flex flex-col md:flex-row items-center justify-between gap-12">
                       <div className={`flex-1 text-center ${language === 'ar' ? 'md:text-right' : 'md:text-left'} order-2 md:order-1`}>
                          <span className="block text-blue-400 text-[10px] font-bold tracking-[0.3em] uppercase mb-4 animate-pulse">{t.bio_tag}</span>
                          <h2 className={`text-3xl md:text-5xl mb-6 font-display font-medium`}>{t.bio_title}</h2>
                          <p className="text-gray-400 text-sm leading-relaxed tracking-wide max-w-md mx-auto md:mx-0 font-sans font-light">{t.bio_desc}</p>
                       </div>
                       <div className="flex-1 flex justify-center md:justify-end order-1 md:order-2">
                            <img src="https://fit-4rce-x.s3.eu-north-1.amazonaws.com/S3Ts_bg_removed_facial_recognition.png" alt="S3Ts Neural Face ID" className="h-64 md:h-96 w-auto object-contain drop-shadow-2xl opacity-90"/>
                       </div>
                   </div>
                </div>
            </section>
            <ProductGrid 
                title={t.tech_title} 
                subtitle={t.tech_subtitle}
                products={PRODUCTS}
                onNavigate={handleNavigate}
                language={language}
            />
          </>
        );
      case 'store':
        return <StorePage onAddToCart={handleAddToCart} language={language} translations={t} selectedProductId={selectedProductId} onProductSelect={(id) => setSelectedProductId(id)} />;
      case 'cart':
        return <CartPage items={cartItems} onUpdateQuantity={handleUpdateQuantity} onRemove={handleRemoveFromCart} onContinueShopping={() => handleNavigate('store')} language={language} translations={t} />;
      case 'telecom':
        return <TelecomPage onNavigate={handleNavigate} language={language} />;
      case 'fintech':
        return <FintechPage onNavigate={handleNavigate} language={language} />;
      case 'fitness':
        return <FitnessPage onNavigate={handleNavigate} language={language} />;
      case 'cv-maker':
        return <CVMakerPage onNavigate={handleNavigate} language={language} />;
      case 'nova-tax':
        return <NovaTaxPage onNavigate={handleNavigate} language={language} />;
      case 'foldable':
        return <FoldablePage onNavigate={handleNavigate} language={language} translations={t} />;
      case 'notebook':
        return <NotebookPage onNavigate={handleNavigate} language={language} translations={t} />;
      case 'investors':
        return <InvestorsPage />;
      case 'about':
        return <AboutPage onNavigate={() => handleNavigate('home')} language={language} translations={t} />;
      default:
        return <Hero onNavigate={handleNavigate} language={language} translations={t} />;
    }
  };

  return (
    <div className={`min-h-screen bg-white text-gray-900 selection:bg-black selection:text-white ${language === 'ar' ? 'font-tajawal' : 'font-sans'}`} dir={language === 'ar' ? 'rtl' : 'ltr'}>
      <Navbar 
        onNavigate={handleNavigate} 
        cartCount={cartItems.reduce((acc, item) => acc + item.quantity, 0)} 
        currentView={currentView} 
        language={language} 
        translations={t} 
      />

      <main className="pt-0">
        {renderView()}
      </main>

      <Footer onNavigate={handleNavigate} language={language} onToggleLanguage={toggleLanguage} translations={t} />
      <ChatSupport language={language} />
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Search, ShoppingBag, User, Menu, X } from 'lucide-react';
import { NAV_ITEMS } from '../constants';
import { Language, AppView } from '../types';

interface NavbarProps {
  onNavigate: (view: AppView, productId?: string) => void;
  cartCount?: number;
  currentView: string;
  language: Language;
  translations: any;
}

const Navbar: React.FC<NavbarProps> = ({ onNavigate, cartCount = 0, currentView, language, translations }) => {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  const handleNavClick = (href: string) => {
    const mapping: Record<string, AppView> = {
      '#home': 'home',
      '#store': 'store',
      '#foldable': 'foldable',
      '#notebook': 'notebook',
      '#holographic': 'chat-web',
      '#telecom': 'telecom',
      '#fintech': 'fintech',
      '#fitness': 'fitness',
      '#cv-maker': 'cv-maker',
      '#nova-tax': 'nova-tax'
    };

    const targetView = mapping[href];
    if (targetView) {
      onNavigate(targetView);
    } else {
      onNavigate('home');
      if (href.startsWith('#')) {
        setTimeout(() => {
          const element = document.querySelector(href);
          element?.scrollIntoView({ behavior: 'smooth' });
        }, 100);
      }
    }
    setMobileMenuOpen(false);
  };

  const fontClass = language === 'ar' ? 'font-tajawal font-bold' : 'font-sans font-medium';

  return (
    <>
      <nav
        className="fixed top-0 w-full z-50 bg-white/95 backdrop-blur-md shadow-sm text-gray-900 transition-all duration-300 h-16 md:h-24 flex items-center"
        dir={language === 'ar' ? 'rtl' : 'ltr'}
      >
        <div className="max-w-[1440px] mx-auto px-6 md:px-12 relative flex items-center justify-between w-full h-full">

          <div className="hidden lg:flex items-center gap-6 flex-1">
            {NAV_ITEMS.slice(0, 5).map((item) => (
              <button
                key={item.label}
                onClick={() => handleNavClick(item.href)}
                className={`text-[9px] xl:text-[10px] tracking-widest uppercase hover:text-gray-500 transition-colors relative group whitespace-nowrap ${fontClass}`}
              >
                {translations[item.label]}
                <span className={`absolute -bottom-2 left-0 w-full h-[1px] bg-black scale-x-0 group-hover:scale-x-100 transition-transform duration-300 ${language === 'ar' ? 'origin-right' : 'origin-left'}`}></span>
              </button>
            ))}
          </div>

          <button 
            className="lg:hidden text-black flex-1 flex justify-start z-50"
            onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
          >
            {mobileMenuOpen ? <X size={20} /> : <Menu size={20} />}
          </button>

          <div className="flex-0 flex justify-center absolute left-1/2 transform -translate-x-1/2 z-50">
            <button onClick={() => onNavigate('home')} className="flex flex-col items-center group">
               <img 
                  src="https://fit-4rce-x.s3.eu-north-1.amazonaws.com/SUM%C4%80MAH_whitelogo_white_bg.jpg" 
                  alt="Sumāmah Logo" 
                  className="h-14 md:h-20 w-auto transition-transform duration-500 group-hover:scale-105"
               />
            </button>
          </div>

          <div className="hidden lg:flex items-center justify-end gap-6 flex-1">
             {NAV_ITEMS.slice(5).map((item) => (
              <button
                key={item.label}
                onClick={() => handleNavClick(item.href)}
                className={`text-[9px] xl:text-[10px] tracking-widest uppercase hover:text-gray-500 transition-colors relative group whitespace-nowrap ${fontClass}`}
              >
                {translations[item.label]}
                <span className={`absolute -bottom-2 left-0 w-full h-[1px] bg-black scale-x-0 group-hover:scale-x-100 transition-transform duration-300 ${language === 'ar' ? 'origin-right' : 'origin-left'}`}></span>
              </button>
            ))}
            <div className={`flex items-center gap-6 ${language === 'ar' ? 'border-r pr-6' : 'border-l pl-6'} border-gray-300/30`}>
                <button className="hover:opacity-60 transition-opacity">
                  <Search size={18} strokeWidth={1} />
                </button>
                <button onClick={() => onNavigate('cart')} className="hover:opacity-60 transition-opacity relative group">
                  <ShoppingBag size={18} strokeWidth={1} />
                  {cartCount > 0 && (
                      <span className="absolute -top-1.5 -right-1.5 w-4 h-4 bg-black text-white text-[8px] font-bold rounded-full flex items-center justify-center">
                          {cartCount}
                      </span>
                  )}
                </button>
                <button className="hover:opacity-60 transition-opacity">
                  <User size={18} strokeWidth={1} />
                </button>
            </div>
          </div>

           <div className="flex lg:hidden items-center justify-end gap-4 flex-1 z-50">
               <button onClick={() => onNavigate('cart')} className="hover:opacity-60 relative">
                  <ShoppingBag size={20} strokeWidth={1} />
                  {cartCount > 0 && (
                      <span className="absolute -top-1 -right-1 w-3 h-3 bg-black rounded-full text-white flex items-center justify-center text-[8px]">{cartCount}</span>
                  )}
                </button>
           </div>
        </div>
      </nav>

      {/* Mobile Menu Drawer */}
      <div className={`fixed inset-0 z-40 lg:hidden pointer-events-none`} dir={language === 'ar' ? 'rtl' : 'ltr'}>
        <div 
            className={`absolute inset-0 bg-black/40 backdrop-blur-sm transition-opacity duration-500 ${mobileMenuOpen ? 'opacity-100 pointer-events-auto' : 'opacity-0'}`} 
            onClick={() => setMobileMenuOpen(false)}
        />
        <div 
            className={`absolute top-0 ${language === 'ar' ? 'right-0 border-l' : 'left-0 border-r'} h-full w-[280px] bg-white shadow-2xl transform transition-transform duration-500 ease-out flex flex-col pt-24 px-8 pointer-events-auto border-gray-100 ${mobileMenuOpen ? 'translate-x-0' : (language === 'ar' ? 'translate-x-full' : '-translate-x-full')}`}
        >
          <div className="flex-1 overflow-y-auto py-8">
            <div className="flex flex-col gap-6">
              {NAV_ITEMS.map((item) => (
                  <button
                    key={item.label}
                    onClick={() => handleNavClick(item.href)}
                    className={`text-xs tracking-[0.25em] uppercase text-gray-900 text-left ${fontClass}`}
                  >
                    {translations[item.label]}
                  </button>
              ))}
            </div>
          </div>
        </div>
      </div>
    </>
  );
};

